:root{

  --bg:#0E111A;

  --panel:#161B29;

  --panel-raised:#1D2436;

  --border:#2A3149;

  --border-soft:#232A40;

  --text:#EDEFF6;

  --text-dim:#9AA3BC;

  --text-mute:#6A7290;

  --flow:#E8A94A;

  --flow-dim:#8a6a35;

  --healthy:#3FC7A6;

  --neglect:#9C8CF5;

  --overused:#E8607A;

  --due:#5AA9E6;

  --radius-s:6px;

  --radius-m:12px;

  --radius-l:20px;

  --font-display:'Fraunces', Georgia, serif;

  --font-body:'Manrope', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

}

