html,body{margin:0;padding:0;}

body{

  background:radial-gradient(ellipse 1200px 800px at 10% -10%, #1A2036 0%, var(--bg) 55%);

  color:var(--text);

  font-family:var(--font-body);

  min-height:100vh;

  -webkit-font-smoothing:antialiased;

}

::selection{background:var(--flow); color:#1a1200;}

a{color:inherit;}

button{font-family:inherit;}

input,select,textarea{font-family:inherit;}

::-webkit-scrollbar{width:10px;height:10px;}

::-webkit-scrollbar-thumb{background:#2a3149;border-radius:8px;}

::-webkit-scrollbar-track{background:transparent;}

#app{display:flex; min-height:100vh;}

/* ---------- Sidebar ---------- */

.sidebar{

  width:var(--sidebar-width,236px); flex-shrink:0;

  background:linear-gradient(180deg, #131826 0%, #10131F 100%);

  border-right:1px solid var(--border-soft);

  display:flex; flex-direction:column;

  padding:26px 16px;

  position:sticky; top:0; height:100vh;

}

.brand{display:flex; align-items:center; gap:10px; padding:0 8px 26px 8px;}

.brand-mark{

  width:34px; height:34px; border-radius:10px;

  background:conic-gradient(from 220deg, var(--flow), var(--healthy), var(--neglect), var(--flow));

  flex-shrink:0;

}

.brand-name{font-family:var(--font-display); font-size:19px; font-weight:600; letter-spacing:0.2px;}

.brand-sub{font-size:11px; color:var(--text-mute); margin-top:1px;}

.nav{display:flex; flex-direction:column; gap:2px; margin-top:8px;}

.nav-item{

  display:flex; align-items:center; gap:11px;

  padding:10px 12px; border-radius:var(--radius-s);

  color:var(--text-dim); cursor:pointer; font-size:14px; font-weight:600;

  border:1px solid transparent; transition:background .15s, color .15s;

  user-select:none;

}

.nav-item svg{width:17px; height:17px; opacity:.85; flex-shrink:0;}

.nav-item:hover{background:var(--panel); color:var(--text);}

.nav-item.active{background:var(--panel-raised); color:var(--text); border-color:var(--border-soft);}

.nav-item.active svg{opacity:1; color:var(--flow);}

.sidebar-foot{margin-top:auto; padding:14px 10px; border-top:1px solid var(--border-soft);}

.sidebar-foot .k{font-size:11px; color:var(--text-mute); text-transform:uppercase; letter-spacing:.06em;}

.sidebar-foot .v{font-family:var(--font-display); font-size:22px; margin-top:2px;}.stats-level-progress-track{height:5px;background:var(--border);border-radius:99px;overflow:hidden;margin-top:0;flex:1;min-width:260px;max-width:520px;} .stats-level-progress-fill{height:100%;background:linear-gradient(90deg,var(--flow-dim),var(--flow));border-radius:99px;transition:width .3s ease;} .sidebar-foot .level-block{margin-top:14px;padding:11px 10px;border:1px solid var(--border-soft);background:var(--panel);border-radius:12px;} .sidebar-foot .level-head{display:flex;align-items:center;justify-content:space-between;gap:8px;} .sidebar-foot .level-title{font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:var(--text-mute);} .sidebar-foot .level-num{font-family:var(--font-display);font-size:18px;font-weight:700;color:var(--flow);} .sidebar-foot .xp-line{display:flex;justify-content:space-between;gap:8px;font-size:10.5px;color:var(--text-dim);margin-top:3px;} .sidebar-foot .xp-track{height:5px;margin-top:8px;background:var(--border);border-radius:99px;overflow:hidden;} .sidebar-foot .xp-fill{height:100%;background:linear-gradient(90deg,var(--flow-dim),var(--flow));border-radius:99px;transition:width .3s ease;} .sidebar-foot .level-next{font-size:10px;color:var(--text-mute);margin-top:6px;}
.sidebar-resizer{position:absolute;top:0;right:-7px;width:14px;height:100%;cursor:col-resize;z-index:100;touch-action:none;user-select:none;-webkit-user-select:none;background:transparent;}
.sidebar-resizer::after{content:'';position:absolute;top:0;bottom:0;left:6px;width:2px;background:transparent;transition:background .15s;}
.sidebar:hover .sidebar-resizer::after,.sidebar-resizer:focus-visible::after{background:var(--flow);}
body.sidebar-resizing{cursor:col-resize;user-select:none;}
body.sidebar-resizing *{cursor:col-resize !important;user-select:none !important;-webkit-user-select:none !important;}
body.sidebar-resizing{overflow:hidden;}
.account-avatar{width:28px;height:28px;border-radius:50%;object-fit:cover;flex-shrink:0;border:1px solid var(--border);background:var(--panel);display:grid;place-items:center;font-size:10px;font-weight:800;color:var(--text-dim);}
.account-avatar-btn{border:0;padding:0;background:transparent;cursor:pointer;border-radius:50%;display:grid;place-items:center;flex-shrink:0;}
.account-avatar-btn:focus-visible{outline:2px solid var(--flow);outline-offset:2px;}
.account-profile-btn{border:0;background:transparent;color:var(--text-dim);padding:0;min-width:0;flex:1;text-align:left;cursor:pointer;font:inherit;}
.account-profile-btn:hover .account-menu-email{color:var(--text);}
.profile-avatar-wrap{display:flex;align-items:center;gap:16px;margin-bottom:20px;}
.profile-avatar{width:88px;height:88px;border-radius:50%;object-fit:cover;border:1px solid var(--border);background:var(--panel-raised);display:grid;place-items:center;font-size:25px;font-weight:800;color:var(--text-dim);overflow:hidden;}
.profile-avatar img{width:100%;height:100%;object-fit:cover;}
.profile-avatar-actions{display:flex;gap:8px;flex-wrap:wrap;}
.profile-note{font-size:11.5px;color:var(--text-mute);line-height:1.55;margin-top:7px;}
.profile-card{max-width:720px;}
.profile-section{margin-bottom:22px;}

/* ---------- Main ---------- */

.main{flex:1; min-width:0; padding:32px 40px 90px 40px;}

.view-head{display:flex; align-items:baseline; justify-content:space-between; margin-bottom:22px; flex-wrap:wrap; gap:10px;}

.view-title{font-family:var(--font-display); font-size:28px; font-weight:600;}

.view-desc{color:var(--text-dim); font-size:13.5px; margin-top:4px;}

.container{max-width:1080px;}

/* ---------- Cards / primitives ---------- */

.card{

  background:var(--panel); border:1px solid var(--border-soft);

  border-radius:var(--radius-m); padding:20px;

}

.hairline{border-top:1px solid var(--border-soft);}

.settings-section-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.settings-section-head .btn{font-size:10px;padding:5px 8px}.section-label{font-size:12px; font-weight:700; color:var(--text-mute); letter-spacing:.04em; margin-bottom:10px;}

.btn{

  display:inline-flex; align-items:center; justify-content:center; gap:7px;

  padding:10px 18px; border-radius:9px; font-size:14px; font-weight:700;

  border:1px solid var(--border); background:var(--panel-raised); color:var(--text);

  cursor:pointer; transition:transform .1s ease, background .15s, border-color .15s;

}

.btn:hover{border-color:#3b4568;}

.btn:active{transform:scale(.97);}

.btn-primary{background:var(--flow); color:#1c1305; border-color:var(--flow);}

.btn-primary:hover{background:#f0b65c;}

.btn-ghost{background:transparent; border-color:transparent; color:var(--text-dim);}

.btn-ghost:hover{color:var(--text); background:var(--panel);}

.btn-danger{background:transparent; border-color:var(--overused); color:var(--overused);}

.btn-danger:hover{background:rgba(232,96,122,.1);}

.btn-sm{padding:7px 12px; font-size:12.5px;}

.btn-block{width:100%;}

.btn:disabled{opacity:.4; cursor:not-allowed;}

.pill{

  display:inline-flex; align-items:center; gap:5px;

  padding:4px 10px; border-radius:99px; font-size:11.5px; font-weight:700;

  background:var(--panel-raised); border:1px solid var(--border-soft); color:var(--text-dim);

}

.dot{width:7px; height:7px; border-radius:50%; flex-shrink:0;}

input[type=text],input[type=number],input[type=date],select,textarea{

  width:100%; background:#12172480; background:#10141F; border:1px solid var(--border);

  color:var(--text); padding:9px 11px; border-radius:8px; font-size:14px; outline:none;

}

input[type=text]:focus,input[type=number]:focus,input[type=date]:focus,select:focus,textarea:focus{border-color:var(--flow-dim);}

/* ============================================================
   MediaFlow v63 — Designed Dropdown System
   Every native select in MediaFlow receives the same polished,
   theme-aware control treatment without changing its behavior.
   ============================================================ */
select{
  -webkit-appearance:none;
  appearance:none;
  min-height:42px;
  padding:10px 42px 10px 13px !important;
  border:1px solid var(--border) !important;
  border-radius:10px;
  color:var(--text) !important;
  background-color:var(--panel-raised) !important;
  background-image:
    linear-gradient(45deg,transparent 50%,var(--text-dim) 50%),
    linear-gradient(135deg,var(--text-dim) 50%,transparent 50%),
    linear-gradient(to right,var(--border-soft),var(--border-soft)) !important;
  background-position:
    calc(100% - 18px) 50%,
    calc(100% - 13px) 50%,
    calc(100% - 37px) 50% !important;
  background-size:5px 5px,5px 5px,1px 20px !important;
  background-repeat:no-repeat !important;
  box-shadow:0 1px 0 rgba(255,255,255,.025),0 5px 16px rgba(0,0,0,.10);
  font:inherit;
  font-size:13px;
  font-weight:650;
  line-height:1.25;
  cursor:pointer;
  transition:border-color .16s ease,box-shadow .16s ease,transform .12s ease,background-color .16s ease;
}
select:hover{
  border-color:var(--flow-dim) !important;
  box-shadow:0 0 0 1px color-mix(in srgb,var(--flow) 14%,transparent),0 7px 20px rgba(0,0,0,.13);
}
select:focus,select:focus-visible{
  outline:none;
  border-color:var(--flow) !important;
  box-shadow:0 0 0 3px color-mix(in srgb,var(--flow) 20%,transparent),0 7px 20px rgba(0,0,0,.14);
}
select:active{transform:translateY(1px);}
select:disabled{
  cursor:not-allowed;
  opacity:.52;
  box-shadow:none;
}
select option,select optgroup{
  color:var(--text);
  background:var(--panel-raised);
  font-weight:600;
}
select option:checked{background:var(--panel);}
select[multiple]{
  min-height:120px;
  padding:8px !important;
  background-image:none !important;
}
select[multiple] option{
  padding:8px 10px;
  border-radius:7px;
  margin:2px 0;
}
.lib-filters select,.mf-batchbar select{
  min-height:38px;
  padding-top:8px !important;
  padding-bottom:8px !important;
}
@media(max-width:640px){
  select{
    min-height:44px;
    font-size:14px;
    padding-left:12px !important;
    padding-right:40px !important;
  }
  .lib-filters select,.mf-batchbar select{
    min-height:42px;
    max-width:100%;
  }
}


label.field-label{display:block; font-size:12px; font-weight:700; color:var(--text-dim); margin-bottom:6px;}

.field{margin-bottom:14px;}

.field-row{display:grid; grid-template-columns:1fr 1fr; gap:12px;}

input[type=range]{-webkit-appearance:none; width:100%; height:4px; background:var(--border); border-radius:3px; outline:none;}

input[type=range]::-webkit-slider-thumb{-webkit-appearance:none; width:15px; height:15px; border-radius:50%; background:var(--flow); cursor:pointer; margin-top:-6px;}

input[type=checkbox]{width:16px; height:16px; accent-color:var(--flow);}

.progress-track{height:8px; background:#10141F; border:1px solid var(--border-soft); border-radius:99px; overflow:hidden;}

.progress-fill{height:100%; border-radius:99px; background:linear-gradient(90deg, var(--flow-dim), var(--flow)); transition:width .4s ease;}

/* ---------- Dashboard ---------- */

.today-strip{display:grid; grid-template-columns:1fr 1fr 1fr; gap:14px; margin-bottom:22px;}

.stat-box{background:var(--panel); border:1px solid var(--border-soft); border-radius:var(--radius-m); padding:16px 18px;}

.stat-box .num{font-family:var(--font-display); font-size:26px; font-weight:600;}

.stat-box .lbl{font-size:12px; color:var(--text-mute); margin-top:2px;}

.stat-box .progress-track{margin-top:10px;}

.hero{

  position:relative; border-radius:var(--radius-l); padding:30px 34px;

  background:linear-gradient(155deg, #1B1F30 0%, #171B29 60%);

  border:1px solid var(--border-soft); overflow:hidden; margin-bottom:26px;

}

