.item-row{display:grid; grid-template-columns:auto 1fr auto auto auto auto; gap:14px; align-items:center; padding:13px 6px; border-bottom:1px solid var(--border-soft);}

.item-row:hover{background:var(--panel-raised);}

.item-title{font-weight:700; font-size:14px;}

.item-sub{font-size:12px; color:var(--text-mute); margin-top:2px;}

.tag{font-size:10.5px; background:var(--panel-raised); border:1px solid var(--border-soft); color:var(--text-mute); padding:2px 7px; border-radius:6px; margin-right:4px;}

.empty-state{padding:60px 20px; text-align:center; color:var(--text-mute);}

.empty-state .em-icon{font-size:38px; margin-bottom:10px;}

.empty-state .em-title{font-family:var(--font-display); font-size:19px; color:var(--text); margin-bottom:6px;}

/* ---------- History ---------- */

.hist-row{display:flex; align-items:flex-start; gap:14px; padding:15px 4px; border-bottom:1px solid var(--border-soft);}

.hist-date{width:96px; flex-shrink:0; font-size:12px; color:var(--text-mute); padding-top:3px;}

.hist-icon{width:36px; height:36px; border-radius:10px; display:flex; align-items:center; justify-content:center; font-size:17px; flex-shrink:0;}

.hist-main{flex:1; min-width:0;}

.hist-cat{font-weight:700; font-size:14px;}

.hist-amt{font-size:13px; color:var(--text-dim); margin-top:2px;}

.hist-note{font-size:12.5px; color:var(--text-mute); margin-top:4px; font-style:italic;}

.hist-status{flex-shrink:0;}

/* ---------- Stats ---------- */

.bal-bar-row{display:flex; align-items:center; gap:12px; margin-bottom:12px;}

.bal-bar-label{width:150px; font-size:13px; font-weight:600; flex-shrink:0; display:flex; align-items:center; gap:7px;}

.bal-bar-track{flex:1; height:14px; background:#10141F; border:1px solid var(--border-soft); border-radius:6px; overflow:hidden;}

.bal-bar-fill{height:100%; border-radius:5px;}

.bal-bar-val{width:70px; text-align:right; font-size:12px; color:var(--text-dim); flex-shrink:0;}

.sat-grid{display:flex; flex-direction:column; gap:10px;}

.sat-row{display:flex; align-items:center; justify-content:space-between; padding:9px 12px; background:var(--panel-raised); border-radius:9px; border:1px solid var(--border-soft);}

.sat-cat{display:flex; align-items:center; gap:9px; font-size:13.5px; font-weight:600;}

.sat-lvl{font-size:11px; font-weight:800; letter-spacing:.03em; padding:3px 10px; border-radius:99px;}

.record-list{display:flex; flex-direction:column; gap:0;}

.record-row{display:flex; justify-content:space-between; padding:11px 2px; border-bottom:1px solid var(--border-soft); font-size:13.5px;}

.record-row:last-child{border-bottom:none;}

.record-row .k{color:var(--text-dim);}

.record-row .v{font-weight:700;}

/* ---------- Settings ---------- */

.intensity-row{display:flex; gap:10px; margin-bottom:6px;}

.intensity-opt{flex:1; padding:13px; border-radius:10px; border:1px solid var(--border); background:var(--panel-raised); cursor:pointer; text-align:center;}

.intensity-opt.active{border-color:var(--flow); background:rgba(232,169,74,.09);}

.intensity-opt .t{font-weight:800; font-size:13.5px;}

.intensity-opt .d{font-size:11px; color:var(--text-mute); margin-top:2px;}

.cat-manage-row{display:flex; align-items:center; gap:12px; padding:12px 4px; border-bottom:1px solid var(--border-soft);}

.cat-manage-row .name{flex:1; font-weight:700; font-size:14px;}

.cat-manage-row .meta{font-size:12px; color:var(--text-mute);}

.toggle{position:relative; width:38px; height:22px; border-radius:99px; background:var(--border); border:none; cursor:pointer; flex-shrink:0;}

.toggle.on{background:var(--flow);}

.toggle::after{content:''; position:absolute; top:2px; left:2px; width:18px; height:18px; border-radius:50%; background:#fff; transition:left .15s;}

.toggle.on::after{left:18px;}

/* ---------- Modal ---------- */

.modal-overlay{position:fixed; inset:0; background:rgba(6,7,12,.65); backdrop-filter:blur(2px); display:flex; align-items:center; justify-content:center; z-index:100; padding:20px;}

.modal{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-l); padding:26px; width:100%; max-width:480px; max-height:88vh; overflow-y:auto;}

