.modal-actions{display:flex; gap:10px; margin-top:20px; justify-content:flex-end;}

.empty-library-modal{max-width:520px;}
.empty-library-icon{width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;background:var(--panel-raised);border:1px solid var(--border);color:var(--flow);margin-bottom:15px;}
.empty-library-icon svg{width:25px;height:25px;}
.empty-library-sub{font-size:13px;line-height:1.6;color:var(--text-dim);margin-bottom:20px;}
