.empty-library-option{width:100%;display:flex;align-items:flex-start;gap:13px;text-align:left;padding:15px;border:1px solid var(--border);border-radius:14px;background:var(--panel-raised);color:var(--text);cursor:pointer;transition:border-color .15s,transform .15s,background .15s;}
.empty-library-option:hover{border-color:var(--flow);transform:translateY(-1px);background:var(--panel-hover,var(--panel-raised));}
.empty-library-option.danger-option:hover{border-color:var(--danger,#ef6b73);}
.empty-option-icon{width:34px;height:34px;flex:0 0 34px;border-radius:10px;display:flex;align-items:center;justify-content:center;background:var(--panel);font-size:16px;}
.empty-library-option b{display:block;font-size:13px;margin-bottom:4px;}
.empty-library-option small{display:block;color:var(--text-dim);font-size:11px;line-height:1.5;}
.empty-library-warning{display:flex;gap:10px;align-items:flex-start;margin-top:15px;padding:11px 12px;border-radius:12px;background:rgba(239,107,115,.07);border:1px solid rgba(239,107,115,.2);color:var(--text-dim);font-size:11px;line-height:1.5;}
.empty-library-warning>span{width:20px;height:20px;flex:0 0 20px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:rgba(239,107,115,.15);color:var(--danger,#ef6b73);font-weight:800;}
.empty-library-warning b{color:var(--text);font-size:12px;}

/* ---------- Mobile ---------- */

.mobile-tabbar{display:none;}

