/* ---- original style block 3: v64-mobile-nav-classic-design ---- */

/* MediaFlow v64 — Classic Mobile Bottom Menu Design
   Keeps v63's responsive navigation logic and More overflow menu, while
   restoring the pre-v63 bottom-bar visual styling. */
@media (max-width:860px){
  .mobile-tabbar{
    display:flex;
    position:fixed;
    bottom:0;
    left:0;
    right:0;
    z-index:50;
    background:#12162299;
    backdrop-filter:blur(10px);
    -webkit-backdrop-filter:blur(10px);
    border-top:1px solid var(--border-soft);
    padding:8px 6px calc(env(safe-area-inset-bottom) + 8px) 6px;
    justify-content:space-around;
    gap:0;
    overflow:visible;
  }
  .mobile-tabbar>.mtab,
  .mobile-more-wrap{
    flex:1 1 0;
    min-width:0;
  }
  .mtab{
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:center;
    gap:3px;
    color:var(--text-mute);
    font-size:10px;
    font-weight:700;
    padding:5px 8px;
    border-radius:9px;
    cursor:pointer;
    user-select:none;
    -webkit-tap-highlight-color:transparent;
  }
  .mtab.active{color:var(--flow);}
  .mtab svg{width:19px;height:19px;}
  .mtab span{
    max-width:100%;
    overflow:hidden;
    text-overflow:ellipsis;
    white-space:nowrap;
  }
  .mobile-more-wrap{position:relative;display:flex;}
  .mobile-more-wrap>.mtab{width:100%;}
}

/* ---- original style block 4: v65-mobile-nav-screenshot-design ---- */

/* MediaFlow v65 — Screenshot-matched mobile navigation
   Visual-only refinement. v63/v64 navigation safety and More fallback remain. */
@media (max-width:860px){
