    background:color-mix(in srgb,var(--bg) 94%,transparent);
    border-top:1px solid var(--border-soft);
    backdrop-filter:blur(14px);
    -webkit-backdrop-filter:blur(14px);
    overflow:visible;
  }

  .mobile-tabbar>.mtab,
  .mobile-more-wrap{
    flex:1 1 0;
    min-width:0;
  }

