/* ---- original style block 15: mf-v136-lifecycle-css ---- */

/* MediaFlow v136 — Start/Finish lifecycle markers */
.heat-cell.v136-heat-start,
.heat-cell.v136-heat-finish{
  position:relative;
  box-sizing:border-box;
}
.heat-cell.v136-heat-start::before{
  content:"";
  position:absolute;
  width:5px;height:5px;
  left:-2px;top:-2px;
  border-radius:50%;
  background:var(--healthy);
  border:1px solid var(--panel);
  box-sizing:border-box;
  z-index:2;
}
.heat-cell.v136-heat-finish::after{
  content:"";
  position:absolute;
  width:5px;height:5px;
  right:-2px;bottom:-2px;
  border-radius:1px;
  background:var(--warning);
  border:1px solid var(--panel);
  box-sizing:border-box;
  z-index:2;
}
.heat-cell.v136-heat-start,
.heat-cell.v136-heat-finish{cursor:help}
.v136-heat-legend{
  display:flex;
  align-items:center;
  gap:12px;
  flex-wrap:wrap;
  margin-top:8px;
  color:var(--text-mute);
  font-size:10px;
}
.v136-heat-legend>span{
  display:inline-flex;
  align-items:center;
  gap:6px;
}
.v136-heat-legend .heat-cell{
  display:inline-block;
  flex:0 0 auto;
}
.v136-otd-event{
  display:inline-flex;
  align-items:center;
  gap:4px;
  width:max-content;
  margin-bottom:3px;
  padding:2px 6px;
  border:1px solid var(--border-soft);
  border-radius:999px;
  background:var(--panel-raised);
  color:var(--text-dim);
  font-size:9px;
  font-weight:800;
  letter-spacing:.04em;
  text-transform:uppercase;
}
.v136-otd-event[data-kind="started"]{color:var(--healthy)}
.v136-otd-event[data-kind="finished"]{color:var(--warning)}
.v136-otd-event[data-kind="logged"]{color:var(--flow)}

