/* ---- original style block 46: mf-v178-rich-metadata-editor-css ---- */

.v178-rich-editor{
  margin-top:14px;
  border:1px solid var(--border-soft);
  border-radius:11px;
  background:var(--panel-raised);
  overflow:hidden;
}
.v178-rich-editor>summary{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  padding:10px 12px;
  cursor:pointer;
  color:var(--text);
  font-size:10.5px;
  font-weight:900;
  list-style:none;
  user-select:none;
}
.v178-rich-editor>summary::-webkit-details-marker{display:none}
.v178-rich-editor>summary::after{
  content:"▾";
  color:var(--text-mute);
  transition:transform .15s ease;
}
.v178-rich-editor[open]>summary::after{transform:rotate(180deg)}
.v178-rich-editor-body{
  padding:0 12px 12px;
}
.v178-rich-editor-note{
  margin:0 0 10px;
  color:var(--text-mute);
  font-size:9px;
  line-height:1.5;
}
.v178-rich-grid{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:9px;
}
.v178-rich-grid .field{
  margin:0;
  min-width:0;
}
.v178-rich-wide{
  grid-column:1/-1;
}
.v178-rich-editor textarea{
  width:100%;
  min-height:112px;
  resize:vertical;
}
.v178-rich-editor input,
.v178-rich-editor textarea{
  min-width:0;
}
.v178-import-lock{
  display:inline-flex;
  align-items:center;
  gap:5px;
  margin-left:7px;
  padding:2px 6px;
  border-radius:999px;
  border:1px solid var(--border-soft);
  color:var(--text-mute);
  font-size:7.5px;
  font-weight:850;
  vertical-align:middle;
}
@media(max-width:650px){
  .v178-rich-grid{grid-template-columns:1fr}
  .v178-rich-wide{grid-column:1}
