/* ============================================================
   MediaFlow v182 — Minimalist Dynamic Library
   Inspired by compact media-library category/status navigation.
   Everything inherits MediaFlow theme variables; no fixed theme colors.
   ============================================================ */

/* The v181 implementation used horizontal overflow for navigation.
   v182 deliberately removes all horizontal scrollbars and lets tabs wrap. */
#view-root .v181-dynamic-nav{
  margin:0 0 16px!important;
  padding:0!important;
  border:0!important;
  border-radius:0!important;
  background:transparent!important;
  box-shadow:none!important;
  overflow:visible!important;
}
#view-root .v181-dynamic-row{
  overflow:visible!important;
  overflow-x:visible!important;
  flex-wrap:wrap!important;
  scrollbar-width:none!important;
}
#view-root .v181-dynamic-row::-webkit-scrollbar{
  display:none!important;
}
#view-root .v181-dynamic-row-label{
  display:none!important;
}
#view-root .v181-dynamic-count{
  display:none!important;
}

/* Category row — text-first tabs with a simple active underline. */
#view-root .v181-dynamic-row:first-child{
  display:flex!important;
  align-items:stretch!important;
  gap:0!important;
  padding:0!important;
  margin:0 0 10px!important;
  border:0!important;
  border-bottom:1px solid var(--border-soft)!important;
  background:transparent!important;
}
#view-root .v181-dynamic-row:first-child .btn{
  position:relative!important;
  flex:0 0 auto!important;
  min-height:38px!important;
  margin:0!important;
  padding:9px 13px 11px!important;
  border:0!important;
  border-radius:0!important;
  background:transparent!important;
  box-shadow:none!important;
  color:var(--text-dim)!important;
  font-size:9px!important;
  font-weight:850!important;
  letter-spacing:.055em!important;
  line-height:1.25!important;
  text-transform:uppercase!important;
  white-space:nowrap!important;
  transition:color .16s ease,background .16s ease!important;
}
#view-root .v181-dynamic-row:first-child .btn:hover{
  color:var(--text)!important;
  background:color-mix(in srgb,var(--panel-raised) 44%,transparent)!important;
}
#view-root .v181-dynamic-row:first-child .btn.active{
  color:var(--text)!important;
  background:transparent!important;
}
#view-root .v181-dynamic-row:first-child .btn::after{
  content:""!important;
  position:absolute!important;
  left:10px!important;
  right:10px!important;
  bottom:-1px!important;
  height:2px!important;
  border-radius:999px 999px 0 0!important;
  background:transparent!important;
  transition:background .16s ease!important;
}
#view-root .v181-dynamic-row:first-child .btn.active::after{
  background:var(--flow)!important;
}

/* Keep the tab row visually clean like the reference. */
#view-root .v181-dynamic-row:first-child .v144-cat-icon-img,
#view-root .v181-dynamic-row:first-child .v144-cat-icon-emoji{
  display:none!important;
}

/* Status row — compact segmented navigation, also fully theme-aware. */
#view-root .v181-dynamic-row + .v181-dynamic-row{
  display:flex!important;
  align-items:stretch!important;
  gap:0!important;
  padding:0!important;
  margin:0!important;
  border:1px solid var(--border-soft)!important;
  border-radius:7px!important;
  background:color-mix(in srgb,var(--panel) 92%,transparent)!important;
  overflow:hidden!important;
}
#view-root .v181-dynamic-row + .v181-dynamic-row .btn{
  flex:1 1 110px!important;
  min-width:0!important;
  min-height:39px!important;
  margin:0!important;
  padding:9px 12px!important;
  border:0!important;
  border-right:1px solid var(--border-soft)!important;
  border-radius:0!important;
  background:transparent!important;
  box-shadow:none!important;
  color:var(--text-dim)!important;
  font-size:9px!important;
  font-weight:760!important;
  line-height:1.25!important;
  text-align:center!important;
  white-space:nowrap!important;
  transition:background .16s ease,color .16s ease!important;
}
#view-root .v181-dynamic-row + .v181-dynamic-row .btn:last-child{
  border-right:0!important;
}
#view-root .v181-dynamic-row + .v181-dynamic-row .btn:hover{
  color:var(--text)!important;
  background:color-mix(in srgb,var(--panel-raised) 58%,transparent)!important;
}
#view-root .v181-dynamic-row + .v181-dynamic-row .btn.active{
  color:var(--text)!important;
  background:var(--panel-raised)!important;
