/* ---------- Theme-specific structural signatures ---------- */
/* AniList: clean tracker dashboard with thin blue rails. */
html[data-theme="fullstyle-anilist"] .card,
html[data-theme="fullstyle-anilist"] .stat-box{border-top:2px solid color-mix(in srgb,var(--flow) 65%,var(--border))!important;}
html[data-theme="fullstyle-anilist"] .nav-item.active{box-shadow:inset 0 -3px 0 var(--flow)!important;}
html[data-theme="fullstyle-anilist"] .library-view-cards .library-item{transition:transform .14s ease!important;}
html[data-theme="fullstyle-anilist"] .library-view-cards .library-item:hover{transform:translateY(-2px)!important;}

/* AniSearch: compact directory/database geometry. */
html[data-theme="fullstyle-anisearch"] .card{padding:15px!important;}
html[data-theme="fullstyle-anisearch"] .item-row,
html[data-theme="fullstyle-anisearch"] .hist-row{padding-top:9px!important;padding-bottom:9px!important;}
html[data-theme="fullstyle-anisearch"] .section-label{border-left:3px solid var(--flow)!important;padding-left:7px!important;}

/* AniWatch: soft rounded streaming shell. */
html[data-theme="fullstyle-aniwatch"] .sidebar{backdrop-filter:blur(18px)!important;}
html[data-theme="fullstyle-aniwatch"] .nav-item.active{border-radius:999px!important;box-shadow:none!important;background:color-mix(in srgb,var(--flow) 16%,var(--panel-raised))!important;}
html[data-theme="fullstyle-aniwatch"] .btn{border-radius:999px!important;}
html[data-theme="fullstyle-aniwatch"] .library-view-cards .library-item{border-radius:18px!important;overflow:hidden!important;}

/* BetaSeries: crisp red status strips. */
html[data-theme="fullstyle-betaseries"] .card{border-left:3px solid color-mix(in srgb,var(--flow) 55%,var(--border-soft))!important;}
html[data-theme="fullstyle-betaseries"] .nav-item.active{box-shadow:inset 3px 0 0 var(--flow)!important;}
html[data-theme="fullstyle-betaseries"] .status-badge{border-radius:4px!important;}

/* Criticker: scoreboard / rating-board feel. */
html[data-theme="fullstyle-criticker"] .stat-box .num,
html[data-theme="fullstyle-criticker"] .record-row .v{font-family:"Courier New",monospace!important;font-weight:900!important;}
html[data-theme="fullstyle-criticker"] .card{border-width:1px!important;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--flow) 5%,transparent)!important;}
html[data-theme="fullstyle-criticker"] .btn-primary{color:#1b1405!important;}

/* EpisodeCalendar: calendar-grid cues. */
html[data-theme="fullstyle-episodecalendar"] .card{background-image:linear-gradient(90deg,color-mix(in srgb,var(--flow) 3%,transparent) 1px,transparent 1px)!important;background-size:64px 100%!important;}
html[data-theme="fullstyle-episodecalendar"] .today-strip .stat-box{border-top:3px solid var(--flow)!important;}
html[data-theme="fullstyle-episodecalendar"] .section-label::before{content:'▦';margin-right:6px;color:var(--flow)!important;}

/* HiAnime: playful lime/purple streaming language. */
html[data-theme="fullstyle-hianime"] .nav-item.active{border-radius:999px!important;box-shadow:none!important;}
html[data-theme="fullstyle-hianime"] .btn-primary{border-radius:999px!important;}
html[data-theme="fullstyle-hianime"] .hero-icon{border-radius:16px!important;transform:rotate(-3deg)!important;}

/* IMDb: bold yellow rails and square information cards. */
html[data-theme="fullstyle-imdb"] .sidebar{box-shadow:inset 0 -3px 0 var(--flow),0 8px 24px rgba(0,0,0,.10)!important;}
html[data-theme="fullstyle-imdb"] .brand-mark{background:var(--flow)!important;border-radius:4px!important;}
html[data-theme="fullstyle-imdb"] .card,
html[data-theme="fullstyle-imdb"] .stat-box{border-radius:4px!important;}
html[data-theme="fullstyle-imdb"] .btn-primary{color:#181818!important;}
html[data-theme="fullstyle-imdb"] .section-label{color:var(--text)!important;border-left:5px solid var(--flow)!important;padding-left:8px!important;}

/* Letterboxd: poster-first cinema layout and three-tone accent line. */
html[data-theme="fullstyle-letterboxd"] .sidebar::after{content:'';position:absolute;left:0;right:0;bottom:-1px;height:3px;background:linear-gradient(90deg,#ff8000 0 33.333%,#00e054 33.333% 66.666%,#40bcf4 66.666%)!important;}
html[data-theme="fullstyle-letterboxd"] .library-view-cards .library-item{transition:transform .15s ease,box-shadow .15s ease!important;}
html[data-theme="fullstyle-letterboxd"] .library-view-cards .library-item:hover{transform:translateY(-4px) scale(1.01)!important;box-shadow:0 14px 28px rgba(0,0,0,.18)!important;}
html[data-theme="fullstyle-letterboxd"] .status-badge{border-radius:999px!important;}

/* LiveChart: schedule-board rails. */
html[data-theme="fullstyle-livechart"] .item-row,
html[data-theme="fullstyle-livechart"] .hist-row{border-left:2px solid color-mix(in srgb,var(--flow) 45%,var(--border-soft))!important;padding-left:10px!important;}
html[data-theme="fullstyle-livechart"] .section-label{border-bottom:2px solid var(--flow)!important;padding-bottom:5px!important;width:max-content!important;}
html[data-theme="fullstyle-livechart"] .today-strip{gap:6px!important;}

/* Kitsu: social-feed cards and rounded interactions. */
html[data-theme="fullstyle-kitsu"] .profile-stat-hero,
html[data-theme="fullstyle-kitsu"] .hero{border-radius:20px!important;}
html[data-theme="fullstyle-kitsu"] .item-row:hover{transform:translateX(2px)!important;}
