/* v107 provenance note: these are MediaFlow-original interpretations inspired by
   the listed services' visual languages; no third-party logos/assets are bundled. */

/* ---- original style block 66: mf-v106-global-appearance ---- */

/*
   This layer is intentionally independent from data-theme.
   Existing and future themes keep their accent, typography and layout identity;
   data-appearance controls the neutral surface/text system globally.
*/
html[data-appearance="light"]{
  --bg:#f5f7fb!important;
  --panel:#ffffff!important;
  --panel-raised:#f0f3f8!important;
  --border:#cbd3df!important;
  --border-soft:#e0e5ec!important;
  --text:#171a21!important;
  --text-dim:#4d586a!important;
  --text-mute:#737f92!important;
  --flow-dim:color-mix(in srgb,var(--flow) 62%,#ffffff)!important;
  color-scheme:light!important;
}
html[data-appearance="dark"]{
  --bg:#0b0e14!important;
  --panel:#141922!important;
  --panel-raised:#1c2330!important;
  --border:#343d4d!important;
  --border-soft:#252d3a!important;
  --text:#f2f4f8!important;
  --text-dim:#b6becb!important;
  --text-mute:#7f8999!important;
  --flow-dim:color-mix(in srgb,var(--flow) 58%,#0b0e14)!important;
  color-scheme:dark!important;
}

/* Root surfaces. These intentionally come after every theme/full-style stylesheet. */
html[data-appearance="light"] body,
html[data-appearance="light"] #app,
html[data-appearance="light"] .main,
html[data-appearance="light"] .auth-screen{
  background:linear-gradient(180deg,color-mix(in srgb,var(--flow) 3%,#ffffff),var(--bg) 280px)!important;
  color:var(--text)!important;
}
html[data-appearance="dark"] body,
html[data-appearance="dark"] #app,
html[data-appearance="dark"] .main,
html[data-appearance="dark"] .auth-screen{
  background:linear-gradient(180deg,color-mix(in srgb,var(--flow) 3%,#111722),var(--bg) 320px)!important;
  color:var(--text)!important;
}

html[data-appearance="light"] .sidebar{
  background:color-mix(in srgb,var(--flow) 3%,#ffffff)!important;
  border-color:var(--border-soft)!important;
  color:var(--text)!important;
}
html[data-appearance="dark"] .sidebar{
  background:color-mix(in srgb,var(--flow) 3%,#11161f)!important;
  border-color:var(--border-soft)!important;
  color:var(--text)!important;
}

/* Shared surfaces. */
html[data-appearance] .card,
html[data-appearance] .stat-box,
html[data-appearance] .profile-stat-hero,
html[data-appearance] .auth-card,
html[data-appearance] .import-card,
html[data-appearance] .modal,
html[data-appearance] .account-menu,
html[data-appearance] .level-block,
html[data-appearance] .reason-explain,
html[data-appearance] .new-entry-box,
html[data-appearance] .mf-batchbar,
html[data-appearance] .v87-log-tools,
html[data-appearance] .v86-log-tools,
html[data-appearance] .v66-cat-panel,
html[data-appearance] .mobile-more-menu,
html[data-appearance] .log-suggestion-list,
html[data-appearance] .v82-repeat-panel,
html[data-appearance] .v82-repeat-grid>div,
html[data-appearance] .sat-row,
html[data-appearance] .score-grid>div,
html[data-appearance] .recap-grid>div,
html[data-appearance] .mf-achievement,
html[data-appearance] .empty-library-option,
html[data-appearance] .v45-cover-choice{
  background:var(--panel)!important;
  border-color:var(--border-soft)!important;
  color:var(--text)!important;
}
html[data-appearance] .hero{
  background:linear-gradient(145deg,color-mix(in srgb,var(--flow) 7%,var(--panel-raised)),var(--panel))!important;
  border-color:var(--border-soft)!important;
  color:var(--text)!important;
}
html[data-appearance] .intensity-opt,
html[data-appearance] .status-choice,
html[data-appearance] .category-choice,
html[data-appearance] .priority-choice,
html[data-appearance] .import-stat,
html[data-appearance] .tag,
html[data-appearance] .pill,
html[data-appearance] .setup-code,
html[data-appearance] .auth-tabs,
html[data-appearance] .v43-rating-grid>div{
  background:var(--panel-raised)!important;
  border-color:var(--border-soft)!important;
  color:var(--text)!important;
}

/* Text hierarchy — important for full styles that previously hard-coded white. */
html[data-appearance] .view-title,
html[data-appearance] .hero-name,
html[data-appearance] .item-title,
html[data-appearance] .hist-cat,
html[data-appearance] .record-row .v,
html[data-appearance] .modal-title,
html[data-appearance] .empty-state .em-title,
html[data-appearance] .auth-title,
html[data-appearance] .auth-brand-name,
html[data-appearance] .import-title,
html[data-appearance] .timeline-title,
html[data-appearance] .v76-otd-copy b,
html[data-appearance] .v76-otd-row-copy b{
  color:var(--text)!important;
}
html[data-appearance] .view-desc,
html[data-appearance] .hero-amount,
html[data-appearance] .item-sub,
html[data-appearance] .hist-amt,
html[data-appearance] .hist-note,
html[data-appearance] .profile-note,
html[data-appearance] .auth-sub,
html[data-appearance] .account-menu-email,
html[data-appearance] .record-row .k,
html[data-appearance] .v43-log-detail,
html[data-appearance] .health-note,
html[data-appearance] .health-action,
html[data-appearance] .field-label,
html[data-appearance] label.field-label,
html[data-appearance] small.hint{
  color:var(--text-dim)!important;
}
html[data-appearance] .section-label{color:var(--flow)!important;}
html[data-appearance] .brand-sub{color:var(--text-mute)!important;}

/* Theme identity is retained through accents. Netflix's red wordmark remains red. */
html[data-appearance="light"][data-theme="fullstyle-myanimelist"] .brand-name,
html[data-appearance="light"][data-theme="fullstyle-crunchyroll"] .brand-name{color:var(--text)!important;}
html[data-appearance="light"][data-theme="fullstyle-crunchyroll"] .brand-mark::after{background:color-mix(in srgb,var(--flow) 3%,#ffffff)!important;}
html[data-appearance="dark"][data-theme="fullstyle-crunchyroll"] .brand-mark::after{background:color-mix(in srgb,var(--flow) 3%,#11161f)!important;}

/* Navigation remains theme-specific in shape/layout, but readable in either mode. */
html[data-appearance] .nav-item{color:var(--text-dim)!important;}
html[data-appearance] .nav-item:hover{color:var(--text)!important;background:color-mix(in srgb,var(--flow) 7%,var(--panel-raised))!important;}
html[data-appearance] .nav-item.active{color:var(--text)!important;}
html[data-appearance] .sidebar-foot>.v{background:var(--panel-raised)!important;border-color:var(--border)!important;color:var(--text)!important;}
html[data-appearance] .sidebar-foot .level-block{background:var(--panel-raised)!important;border-color:var(--border)!important;}
html[data-appearance] .sidebar-foot .xp-line{color:var(--text-dim)!important;}
html[data-appearance] .sidebar-foot .xp-track{background:var(--border)!important;}

/* Form controls and secondary buttons. Primary buttons keep the theme accent. */
html[data-appearance] input[type=text],
html[data-appearance] input[type=number],
html[data-appearance] input[type=email],
html[data-appearance] input[type=password],
html[data-appearance] input[type=url],
html[data-appearance] input[type=date],
html[data-appearance] input[type=time],
html[data-appearance] select,
html[data-appearance] textarea{
  background-color:var(--panel-raised)!important;
  color:var(--text)!important;
  border-color:var(--border)!important;
}
html[data-appearance] select option,
