  :where(.v221-settings-nav,.v221-settings-toolbar){scrollbar-width:thin}
  .v221-settings-nav-item{min-height:40px}
  .mf-batchbar{max-width:100%;overflow-x:auto;overscroll-behavior-x:contain}
}

