.v247-diag-badge.is-fail{border-color:color-mix(in srgb,#ff6b7a 42%,var(--border-soft));color:#ff7d8b;background:color-mix(in srgb,#ff6b7a 9%,var(--panel-raised))}
.v247-diag-badge.is-info{color:var(--flow);border-color:color-mix(in srgb,var(--flow) 35%,var(--border-soft));background:color-mix(in srgb,var(--flow) 8%,var(--panel-raised))}
.v247-pwa-diagnostics{width:100%;border-top:1px solid var(--border-soft);padding-top:12px}
.v247-pwa-diagnostics>summary{display:flex;align-items:center;justify-content:space-between;gap:12px;cursor:pointer;list-style:none;font-size:11px;font-weight:800;color:var(--text);user-select:none;min-height:34px}
