/* --- assets/css/117-v248-settings-update-install.css --- */
/* ============================================================
   MediaFlow v248 — Settings navigation + managed app updates
   ============================================================ */

/* Desktop Settings layout scales with the available viewport rather than
   holding a rigid left rail until the old tablet breakpoint. */
@media (min-width:1181px){
  .v221-settings-layout{grid-template-columns:clamp(188px,17vw,245px) minmax(0,1fr)}
  .v221-settings-nav{min-width:0}
}

/* Narrow desktop / wide tablet: use the horizontal Settings navigator before
   the app content becomes cramped. Mouse/pen drag scrolling is supplied by the
   v248 runtime; touch keeps native horizontal panning. */
@media (min-width:701px) and (max-width:1180px){
  .v221-settings-layout{grid-template-columns:minmax(0,1fr)!important}
  .v221-settings-nav{position:sticky!important;top:104px!important;z-index:20!important;max-height:none!important;display:flex!important;gap:8px!important;overflow-x:auto!important;overflow-y:hidden!important;padding:8px!important;scrollbar-width:thin;overscroll-behavior-x:contain;scroll-snap-type:x proximity;-webkit-overflow-scrolling:touch}
  .v221-settings-nav-group{display:flex!important;align-items:center!important;gap:6px!important;flex:0 0 auto!important;margin:0!important;padding:0!important;border:0!important}
  .v221-settings-nav-title{display:none!important}
  .v221-settings-nav-item{width:auto!important;white-space:nowrap!important;flex:0 0 auto!important;border:1px solid var(--border-soft)!important;background:var(--panel-raised)!important;scroll-snap-align:nearest}
}
.v221-settings-nav.v248-drag-ready{cursor:grab;user-select:none}
.v221-settings-nav.v248-dragging{cursor:grabbing!important;scroll-snap-type:none!important}
.v221-settings-nav.v248-dragging .v221-settings-nav-item{pointer-events:none}

/* Shared dynamic update icon */
.v248-update-icon{display:inline-grid;place-items:center;width:17px;height:17px;flex:0 0 17px;color:currentColor}
.v248-update-icon svg{width:100%;height:100%;display:block}
.v248-update-icon.is-checking svg,.v248-update-icon.is-installing svg{animation:v248UpdateSpin 1s linear infinite;transform-origin:50% 50%}
@keyframes v248UpdateSpin{to{transform:rotate(360deg)}}
.v248-update-icon.is-available{color:#f2b84b}
