.v256-runtime-time-fields label{display:grid;gap:4px;min-width:0}
.v256-runtime-time-fields label>span{font-size:9px;font-weight:800;color:var(--text-mute);text-transform:uppercase;letter-spacing:.05em;text-align:center}
.v256-runtime-time-fields input{text-align:center;font-variant-numeric:tabular-nums;min-width:0;width:100%;box-sizing:border-box}
