.v256-runtime-result{display:grid;gap:10px;padding:13px;border:1px solid var(--border-soft);border-radius:12px;background:color-mix(in srgb,var(--panel-raised) 76%,transparent)}
.v256-runtime-result.has-result{border-color:color-mix(in srgb,var(--flow) 42%,var(--border));background:color-mix(in srgb,var(--flow) 6%,var(--panel-raised))}
.v256-runtime-result-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
.v256-runtime-result-head>div{display:grid;gap:2px}
