.v256-runtime-result-fields>div{display:grid;gap:4px;text-align:center;padding:9px;border:1px solid var(--border-soft);border-radius:9px;background:var(--panel)}
.v256-runtime-result-fields span{font-size:8.5px;color:var(--text-mute);font-weight:800;text-transform:uppercase;letter-spacing:.05em}
.v256-runtime-result-fields output{font-family:var(--font-display);font-size:18px;color:var(--flow);font-variant-numeric:tabular-nums}
.v256-runtime-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px}
.v256-runtime-help{margin-top:10px;font-size:10.5px;color:var(--text-mute);line-height:1.5}

