/* --- assets/css/127-v260-react-redesign.css --- */
/* ========================================================================
   MediaFlow v260 — Professional React-era Design System
   Runtime CSS is prebuilt for zero-config GitHub Pages deployment.
   All colors derive from existing MediaFlow theme variables so dynamic,
   light, AMOLED and full-style themes continue to work.
   ======================================================================== */
:root{
  --v260-bg:var(--bg);
  --v260-surface:color-mix(in srgb,var(--panel) 92%,transparent);
  --v260-surface-2:color-mix(in srgb,var(--panel-raised) 90%,transparent);
  --v260-surface-3:color-mix(in srgb,var(--panel-raised) 72%,var(--bg));
  --v260-line:color-mix(in srgb,var(--border) 72%,transparent);
  --v260-line-strong:color-mix(in srgb,var(--border) 92%,var(--text) 8%);
  --v260-accent:var(--flow);
  --v260-accent-soft:color-mix(in srgb,var(--flow) 16%,transparent);
  --v260-accent-faint:color-mix(in srgb,var(--flow) 7%,transparent);
  --v260-good:var(--healthy);
  --v260-danger:var(--overused);
  --v260-info:var(--due);
  --v260-purple:var(--neglect);
  --v260-shadow:0 18px 60px rgba(0,0,0,.22);
  --v260-shadow-soft:0 10px 34px rgba(0,0,0,.12);
  --v260-radius-xs:8px;
  --v260-radius-s:10px;
  --v260-radius-m:14px;
  --v260-radius-l:20px;
  --v260-radius-xl:28px;
  --v260-content:1440px;
  --v260-font:var(--font-body);
  --v260-display:var(--font-display);
}

html{scroll-behavior:smooth;}
body.v260-redesign{
  background:
    radial-gradient(900px 500px at 76% -120px,color-mix(in srgb,var(--flow) 8%,transparent),transparent 68%),
    radial-gradient(900px 680px at -180px 45%,color-mix(in srgb,var(--due) 6%,transparent),transparent 72%),
    var(--bg);
  font-family:var(--v260-font);
  letter-spacing:-.008em;
}
body.v260-redesign::before{
  content:"";position:fixed;inset:0;pointer-events:none;z-index:-1;
  background-image:linear-gradient(color-mix(in srgb,var(--text) 1.5%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--text) 1.5%,transparent) 1px,transparent 1px);
  background-size:48px 48px;mask-image:linear-gradient(to bottom,rgba(0,0,0,.35),transparent 58%);opacity:.28;
}
body.v260-redesign *{scrollbar-color:color-mix(in srgb,var(--text-mute) 36%,transparent) transparent;}
body.v260-redesign *:focus-visible{outline:2px solid color-mix(in srgb,var(--flow) 88%,white 12%);outline-offset:2px;}
body.v260-redesign ::selection{background:color-mix(in srgb,var(--flow) 75%,transparent);color:var(--text);}

/* App shell ---------------------------------------------------------------- */
body.v260-redesign #app{align-items:stretch;}
body.v260-redesign .sidebar{
  width:var(--sidebar-width,252px);padding:22px 14px 18px;gap:4px;
  background:linear-gradient(180deg,color-mix(in srgb,var(--panel) 93%,var(--bg)) 0%,color-mix(in srgb,var(--bg) 96%,var(--panel)) 100%);
  border-right:1px solid var(--v260-line);box-shadow:12px 0 38px rgba(0,0,0,.08);backdrop-filter:blur(20px);
}
body.v260-redesign .brand{padding:4px 9px 21px;gap:12px;}
body.v260-redesign .brand-mark{
  width:38px;height:38px;border-radius:12px;background:linear-gradient(145deg,color-mix(in srgb,var(--flow) 96%,white 4%),color-mix(in srgb,var(--flow) 62%,var(--due)));
  box-shadow:0 8px 26px color-mix(in srgb,var(--flow) 22%,transparent);position:relative;transform:rotate(2deg);
}
body.v260-redesign .brand-mark::after{content:"";position:absolute;inset:10px 12px;border:2px solid color-mix(in srgb,var(--bg) 75%,white 25%);border-left-width:5px;clip-path:polygon(0 0,100% 50%,0 100%);opacity:.85;}
body.v260-redesign .brand-name{font-family:var(--v260-font);font-size:17px;font-weight:800;letter-spacing:-.03em;}
body.v260-redesign .brand-sub{font-size:10px;text-transform:uppercase;letter-spacing:.16em;color:var(--text-mute);}
body.v260-redesign .nav{gap:5px;margin-top:2px;}
body.v260-redesign .nav-item{
  min-height:42px;padding:10px 12px;border-radius:11px;font-size:13px;font-weight:700;color:var(--text-dim);border:1px solid transparent;
  transition:background .18s ease,color .18s ease,border-color .18s ease,transform .18s ease,box-shadow .18s ease;
}
body.v260-redesign .nav-item:hover{background:color-mix(in srgb,var(--panel-raised) 68%,transparent);color:var(--text);transform:translateX(2px);}
body.v260-redesign .nav-item.active{
  color:var(--text);background:linear-gradient(90deg,color-mix(in srgb,var(--flow) 14%,var(--panel-raised)),color-mix(in srgb,var(--panel-raised) 76%,transparent));
  border-color:color-mix(in srgb,var(--flow) 28%,var(--border));box-shadow:inset 3px 0 0 var(--flow),0 8px 22px rgba(0,0,0,.08);
}
body.v260-redesign .nav-item svg{width:18px;height:18px;stroke-width:1.9;}
body.v260-redesign .sidebar-foot{padding:16px 9px 4px;border-top:1px solid var(--v260-line);}
body.v260-redesign .account-menu{border:1px solid var(--v260-line);background:var(--v260-surface-2);border-radius:13px;padding:8px;box-shadow:var(--v260-shadow-soft);}
body.v260-redesign .cloud-badge{background:color-mix(in srgb,var(--healthy) 12%,transparent);border-color:color-mix(in srgb,var(--healthy) 34%,transparent);color:var(--healthy);}
body.v260-redesign .sidebar-foot .level-block{background:color-mix(in srgb,var(--panel-raised) 66%,transparent);border-color:var(--v260-line);border-radius:13px;}
body.v260-redesign .sidebar-foot .xp-track{height:4px;}

body.v260-redesign .main{padding:18px clamp(18px,2.8vw,46px) 100px;min-width:0;}
body.v260-redesign .container{max-width:var(--v260-content);margin:0 auto;}
body.v260-redesign .v260-react-host{max-width:var(--v260-content);margin:0 auto 18px;min-height:0;}
body.v260-redesign .mobile-tabbar{background:color-mix(in srgb,var(--panel) 94%,transparent);border-top:1px solid var(--v260-line);backdrop-filter:blur(22px);}

/* React top chrome ---------------------------------------------------------- */
.v260-topbar{display:flex;align-items:center;gap:14px;min-height:54px;padding:8px 12px;border:1px solid var(--v260-line);border-radius:16px;background:color-mix(in srgb,var(--panel) 75%,transparent);backdrop-filter:blur(18px);box-shadow:0 8px 28px rgba(0,0,0,.08);}
.v260-topbar-main{min-width:0;display:flex;align-items:center;gap:11px;flex:1;}
.v260-topbar-mark{width:30px;height:30px;border-radius:10px;background:linear-gradient(145deg,var(--flow),color-mix(in srgb,var(--flow) 55%,var(--due)));display:grid;place-items:center;color:color-mix(in srgb,var(--bg) 86%,#fff 14%);font-weight:900;box-shadow:0 7px 22px color-mix(in srgb,var(--flow) 18%,transparent);}
.v260-topbar-copy{display:flex;flex-direction:column;min-width:0;}
.v260-topbar-copy b{font-size:13px;line-height:1.1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.v260-topbar-copy span{font-size:10px;color:var(--text-mute);margin-top:3px;}
.v260-topbar-actions{display:flex;gap:8px;align-items:center;}
.v260-topbar-chip{display:inline-flex;align-items:center;gap:6px;padding:7px 9px;border-radius:9px;border:1px solid var(--v260-line);color:var(--text-dim);font-size:10.5px;font-weight:800;background:color-mix(in srgb,var(--panel-raised) 55%,transparent);}
.v260-topbar button{min-height:34px;}

/* Typography ---------------------------------------------------------------- */
body.v260-redesign .view-head{align-items:flex-end;margin:0 0 18px;gap:16px;}
body.v260-redesign .view-title{font-family:var(--v260-display);font-size:clamp(28px,3.3vw,42px);font-weight:650;letter-spacing:-.045em;line-height:1.02;}
body.v260-redesign .view-desc{font-size:12.5px;line-height:1.55;color:var(--text-dim);max-width:760px;}
body.v260-redesign .section-label{font-size:10.5px;letter-spacing:.11em;text-transform:uppercase;font-weight:800;color:var(--text-mute);}
body.v260-redesign h1,body.v260-redesign h2,body.v260-redesign h3{letter-spacing:-.035em;}

/* Primitives ---------------------------------------------------------------- */
body.v260-redesign .card,
body.v260-redesign .hero,
body.v260-redesign .settings-group,
body.v260-redesign .v221-settings-page-group,
body.v260-redesign .v138-order-view .card{
  border:1px solid var(--v260-line);background:linear-gradient(180deg,color-mix(in srgb,var(--panel) 96%,transparent),color-mix(in srgb,var(--panel) 88%,var(--bg)));
  border-radius:var(--v260-radius-m);box-shadow:0 10px 34px rgba(0,0,0,.08);
}
body.v260-redesign .card{padding:18px;}
body.v260-redesign .btn{
  min-height:38px;padding:8px 14px;border-radius:10px;border-color:var(--v260-line-strong);background:color-mix(in srgb,var(--panel-raised) 78%,transparent);
  font-size:12px;font-weight:800;letter-spacing:-.01em;box-shadow:0 2px 10px rgba(0,0,0,.04);transition:transform .16s ease,border-color .16s ease,background .16s ease,box-shadow .16s ease,color .16s ease;
}
body.v260-redesign .btn:hover{border-color:color-mix(in srgb,var(--flow) 38%,var(--border));background:color-mix(in srgb,var(--panel-raised) 91%,var(--flow) 9%);box-shadow:0 7px 20px rgba(0,0,0,.09);transform:translateY(-1px);}
body.v260-redesign .btn:active{transform:translateY(0) scale(.985);}
body.v260-redesign .btn-primary{background:linear-gradient(135deg,color-mix(in srgb,var(--flow) 97%,white 3%),color-mix(in srgb,var(--flow) 78%,#ffca70));color:#17120a;border-color:color-mix(in srgb,var(--flow) 84%,white 16%);box-shadow:0 8px 26px color-mix(in srgb,var(--flow) 18%,transparent);}
body.v260-redesign .btn-primary:hover{background:linear-gradient(135deg,color-mix(in srgb,var(--flow) 94%,white 6%),color-mix(in srgb,var(--flow) 70%,#ffd994));}
body.v260-redesign .btn-ghost{background:transparent;border-color:transparent;box-shadow:none;}
body.v260-redesign .btn-danger{background:color-mix(in srgb,var(--overused) 6%,transparent);border-color:color-mix(in srgb,var(--overused) 50%,var(--border));}
body.v260-redesign .btn-sm{min-height:32px;padding:6px 10px;font-size:11px;}
body.v260-redesign input:not([type=checkbox]):not([type=radio]),
body.v260-redesign select,
body.v260-redesign textarea{
  min-height:40px;border:1px solid var(--v260-line-strong);border-radius:10px;background:color-mix(in srgb,var(--bg) 32%,var(--panel-raised));color:var(--text);font-size:12px;padding:9px 11px;box-shadow:inset 0 1px 0 color-mix(in srgb,var(--text) 2%,transparent);transition:border-color .16s ease,box-shadow .16s ease,background .16s ease;
}
body.v260-redesign input:hover,body.v260-redesign select:hover,body.v260-redesign textarea:hover{border-color:color-mix(in srgb,var(--text-mute) 50%,var(--border));}
body.v260-redesign input:focus,body.v260-redesign select:focus,body.v260-redesign textarea:focus{border-color:color-mix(in srgb,var(--flow) 58%,var(--border));box-shadow:0 0 0 3px color-mix(in srgb,var(--flow) 10%,transparent);outline:none;}
body.v260-redesign .toggle{border-color:var(--v260-line-strong);background:color-mix(in srgb,var(--panel-raised) 90%,var(--bg));}
body.v260-redesign .toggle.on{background:color-mix(in srgb,var(--flow) 78%,var(--panel-raised));border-color:var(--flow);}
body.v260-redesign .pill,body.v260-redesign .status-badge{border-radius:999px;border-color:var(--v260-line);}
body.v260-redesign .empty-state{border:1px dashed color-mix(in srgb,var(--border) 90%,transparent);border-radius:16px;padding:34px;background:color-mix(in srgb,var(--panel) 44%,transparent);}
body.v260-redesign .health-note,body.v260-redesign .hint,body.v260-redesign .v66-note{font-size:11px;line-height:1.6;color:var(--text-mute);}

/* Modal system --------------------------------------------------------------- */
body.v260-redesign .modal-backdrop{backdrop-filter:blur(10px);background:rgba(0,0,0,.58);}
body.v260-redesign .modal{
  border:1px solid color-mix(in srgb,var(--border) 80%,var(--text) 4%);border-radius:20px;background:linear-gradient(180deg,color-mix(in srgb,var(--panel) 98%,transparent),color-mix(in srgb,var(--panel) 92%,var(--bg)));
  box-shadow:0 32px 100px rgba(0,0,0,.48);overflow:hidden;
}
body.v260-redesign .modal-head{padding:17px 20px;border-bottom:1px solid var(--v260-line);background:color-mix(in srgb,var(--panel-raised) 30%,transparent);}
body.v260-redesign .modal-body{padding:20px;}
body.v260-redesign .modal-actions{padding:14px 20px;border-top:1px solid var(--v260-line);background:color-mix(in srgb,var(--panel-raised) 20%,transparent);}

/* Dashboard ------------------------------------------------------------------ */
body.v260-redesign .hero{position:relative;overflow:hidden;padding:24px;border-color:color-mix(in srgb,var(--flow) 18%,var(--border));}
body.v260-redesign .hero::before{content:"";position:absolute;inset:0;background:radial-gradient(600px 260px at 100% 0,color-mix(in srgb,var(--flow) 9%,transparent),transparent 70%);pointer-events:none;}
body.v260-redesign .hero-eyebrow{font-size:10px;letter-spacing:.13em;text-transform:uppercase;color:var(--flow);font-weight:900;}
body.v260-redesign .hero-name{font-family:var(--v260-display);font-size:clamp(24px,3vw,34px);font-weight:650;letter-spacing:-.04em;}
body.v260-redesign .hero-icon{border-radius:13px;border:1px solid color-mix(in srgb,currentColor 18%,transparent);box-shadow:0 8px 26px rgba(0,0,0,.13);}
body.v260-redesign .dash-grid,body.v260-redesign .dashboard-grid{gap:14px;}
