.v260-history-tabs::-webkit-scrollbar{display:none;}
.v260-history-tab{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;padding:8px 13px;white-space:nowrap;border:0;border-radius:9px;background:transparent;color:var(--text-mute);font:inherit;font-size:11px;font-weight:800;cursor:pointer;transition:background .16s ease,color .16s ease,box-shadow .16s ease;}
