.v260-history-tab.active{color:var(--text);background:color-mix(in srgb,var(--flow) 10%,var(--panel-raised));box-shadow:inset 0 -2px 0 var(--flow),0 4px 12px rgba(0,0,0,.06);}
.v260-history-body{min-width:0;}
.v260-insight-panel{display:grid;grid-template-columns:minmax(230px,1.1fr) 2.8fr;gap:12px;padding:15px;border:1px solid var(--v260-line);border-radius:17px;background:linear-gradient(130deg,color-mix(in srgb,var(--panel-raised) 56%,transparent),color-mix(in srgb,var(--panel) 90%,transparent));margin-bottom:13px;}
.v260-insight-intro{display:flex;align-items:center;gap:14px;padding:11px;}
.v260-insight-icon{width:52px;height:52px;border-radius:15px;display:grid;place-items:center;font-size:28px;color:var(--healthy);background:color-mix(in srgb,var(--healthy) 10%,var(--panel-raised));border:1px solid color-mix(in srgb,var(--healthy) 24%,var(--border));}
.v260-insight-intro strong{display:block;font-family:var(--v260-display);font-size:28px;line-height:1;letter-spacing:-.04em;}
.v260-insight-intro small{display:block;margin-top:4px;color:var(--text-mute);font-size:10px;}
.v260-insight-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--v260-line);border-radius:13px;overflow:hidden;background:color-mix(in srgb,var(--bg) 18%,transparent);}
.v260-insight-grid>div{padding:12px 13px;border-right:1px solid var(--v260-line);min-width:0;}
.v260-insight-grid>div:last-child{border-right:0;}
.v260-insight-grid span,.v260-ratings-summary span{display:block;font-size:9px;text-transform:uppercase;letter-spacing:.1em;color:var(--text-mute);}
.v260-insight-grid b,.v260-ratings-summary b{display:block;margin-top:5px;font-size:15px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.v260-insight-grid small,.v260-ratings-summary small{display:block;margin-top:3px;font-size:9.5px;color:var(--text-mute);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.v260-consumption-history .v241-history-toolbar,.v260-library-history-embed .lib-toolbar{position:sticky;top:10px;z-index:15;backdrop-filter:blur(18px);}
.v260-consumption-history .v253-history-card{padding:4px 14px;}
body.v260-redesign .hist-row{grid-template-columns:auto 104px 40px minmax(0,1fr) auto!important;padding:12px 3px;border-bottom:1px solid var(--v260-line);gap:12px;align-items:center;}
