.v260-recent-toolbar{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;padding:14px 2px 16px;}
.v260-recent-toolbar>div{display:flex;flex-direction:column;gap:3px;}.v260-recent-toolbar b{font-size:15px;}.v260-recent-toolbar span{color:var(--text-mute);font-size:10.5px;}
.v260-recent-timeline{position:relative;padding-left:17px;}.v260-recent-timeline::before{content:"";position:absolute;left:4px;top:12px;bottom:18px;width:1px;background:linear-gradient(var(--due),color-mix(in srgb,var(--due) 12%,transparent));}
.v260-recent-day{position:relative;margin-bottom:18px;padding:0 0 7px 15px;}.v260-recent-day>header{display:flex;align-items:center;gap:8px;min-height:30px;margin-bottom:9px;}.v260-recent-day>header b{font-size:10.5px;text-transform:uppercase;letter-spacing:.06em;}.v260-recent-day>header small{font-size:9px;color:var(--text-mute);}.v260-timeline-dot{position:absolute;left:-16px;width:11px;height:11px;border-radius:50%;background:var(--panel);border:3px solid var(--due);box-shadow:0 0 0 4px color-mix(in srgb,var(--due) 10%,transparent);}
.v260-daypart{margin-bottom:13px;}.v260-daypart-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:7px;color:var(--text-dim);}.v260-daypart-head span{font-size:9.5px;font-weight:900;text-transform:uppercase;letter-spacing:.08em;}.v260-daypart-head small{font-size:8.5px;color:var(--text-mute);}
.v260-recent-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px;}
.v260-recent-card{display:flex;gap:9px;align-items:center;min-height:74px;padding:8px;text-align:left;border:1px solid var(--v260-line);border-radius:12px;background:color-mix(in srgb,var(--panel) 88%,transparent);color:var(--text);font:inherit;cursor:pointer;transition:transform .16s ease,border-color .16s ease,background .16s ease;}
.v260-recent-card:hover{transform:translateY(-2px);border-color:color-mix(in srgb,var(--due) 32%,var(--border));background:color-mix(in srgb,var(--panel-raised) 70%,var(--panel));}
.v260-recent-cover,.v260-rating-cover{width:43px;height:58px;border-radius:8px;background:var(--panel-raised);overflow:hidden;display:grid;place-items:center;flex:0 0 auto;border:1px solid var(--v260-line);}
.v260-recent-cover img,.v260-rating-cover img{width:100%;height:100%;object-fit:cover;}
.v260-recent-copy{display:flex;flex-direction:column;min-width:0;gap:2px;}.v260-recent-copy small{font-size:8px;text-transform:uppercase;letter-spacing:.07em;color:var(--text-mute);}.v260-recent-copy b{font-size:11.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}.v260-recent-copy em{font-size:9px;color:var(--text-mute);font-style:normal;}
.v260-ratings-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-bottom:10px;}.v260-ratings-summary>div{border:1px solid var(--v260-line);background:var(--v260-surface);border-radius:13px;padding:13px 14px;}
.v260-ratings-list{border:1px solid var(--v260-line);border-radius:16px;background:var(--v260-surface);overflow:hidden;}
.v260-rating-row{display:grid;grid-template-columns:42px 44px minmax(0,1fr) minmax(180px,auto) auto;gap:11px;align-items:center;padding:10px 13px;border-bottom:1px solid var(--v260-line);}.v260-rating-row:last-child{border-bottom:0;}.v260-rating-rank{font-family:var(--v260-display);font-size:16px;color:var(--text-mute);text-align:center;}.v260-rating-main{min-width:0;}.v260-rating-main b{display:block;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}.v260-rating-main span{display:block;margin-top:3px;font-size:9px;color:var(--text-mute);}.v260-rating-score{text-align:right;}.v260-rating-score strong{font-size:14px;color:var(--flow);}.v260-rating-score span{display:block;color:var(--flow);font-size:10px;letter-spacing:1px;margin-top:2px;white-space:nowrap;}
.v260-empty{display:grid;place-items:center;text-align:center;min-height:280px;border:1px dashed var(--v260-line);border-radius:18px;background:color-mix(in srgb,var(--panel) 55%,transparent);}.v260-empty b{font-size:15px;}.v260-empty span{font-size:10.5px;color:var(--text-mute);margin-top:-90px;}

/* Animated but restrained ---------------------------------------------------- */
body.v260-redesign .fade-in{animation:v260-enter .22s cubic-bezier(.2,.75,.25,1);}
