  body.v260-redesign .hist-row{grid-template-columns:auto 36px minmax(0,1fr) auto!important;}.hist-date{display:none!important;}.hist-icon{grid-column:2;}.hist-main{grid-column:3;}.hist-status{grid-column:4;}
}
@media(max-width:480px){
  body.v260-redesign .main{padding-inline:8px;}
  .v260-topbar{padding:7px 8px;}.v260-topbar-copy span{display:none;}.v260-topbar-actions .btn span{display:none;}
  .v260-page-hero{padding:17px 16px;border-radius:16px;}.v260-page-hero p{font-size:11px;}.v260-history-tabs{border-radius:11px;gap:2px;padding:4px;}.v260-history-tab{padding:7px 8px;font-size:10px;gap:5px;}.v260-history-tab svg{width:13px;height:13px;}
  .v260-insight-grid{grid-template-columns:1fr;}.v260-insight-grid>div{border-right:0!important;border-bottom:1px solid var(--v260-line)!important;}.v260-insight-grid>div:last-child{border-bottom:0!important;}
  .v260-recent-grid{grid-template-columns:1fr;}.v260-daypart-head small{display:none;}.v260-recent-toolbar{align-items:flex-start;flex-direction:column;}
