}

/* --- assets/css/128-v261-library-history-balance-polish.css --- */
/* ============================================================
   MediaFlow v261 — Library, History, Balance & page icon polish
   ============================================================ */

/* real MediaFlow app mark */
body.v260-redesign .brand-mark{
  background:transparent url('../icons/mediaflow-192.png') center/cover no-repeat!important;
  box-shadow:0 8px 28px color-mix(in srgb,var(--flow) 22%,transparent)!important;
  transform:none!important;border-radius:12px!important;overflow:hidden;
}
body.v260-redesign .brand-mark::after{display:none!important;}

/* page header icon = same semantic page icon family as sidebar */
.v260-topbar-mark.v261-page-icon{
  display:grid;place-items:center;width:34px;height:34px;border-radius:11px;
  background:color-mix(in srgb,var(--flow) 18%,var(--panel-raised));
  color:color-mix(in srgb,var(--flow) 88%,white 12%);
  border:1px solid color-mix(in srgb,var(--flow) 34%,var(--border));
  box-shadow:0 7px 20px color-mix(in srgb,var(--flow) 13%,transparent);
}
.v260-topbar-mark.v261-page-icon svg{width:18px;height:18px;}
.v260-topbar-chip[title="Current dynamic theme"]{display:none!important;}

/* Library ---------------------------------------------------------------- */
.v261-library-page{position:relative;display:flex;flex-direction:column;gap:12px;}
.v261-library-page>.view-head{margin-bottom:0!important;}
.v261-library-page>.view-head .v261-library-tools-toggle{margin-left:auto;}
.v261-library-tools{
  border:1px solid var(--v260-line);border-radius:16px;background:var(--v260-surface);
  box-shadow:var(--v260-shadow-soft);overflow:hidden;transition:border-color .18s ease,background .18s ease;
