/* --- assets/css/129-v262-library-restore.css --- */
/* ============================================================
   MediaFlow v262 — Library restoration
   Uses the preferred cancelled-v260 Library composition over the v261
   runtime without changing any non-Library page.
   ============================================================ */
html[data-mf262-library="1"]{
  --mf262-surface:color-mix(in srgb,var(--panel) 92%,var(--bg));
  --mf262-surface-strong:color-mix(in srgb,var(--panel-raised) 94%,var(--panel));
  --mf262-surface-soft:color-mix(in srgb,var(--panel-raised) 65%,transparent);
  --mf262-line:color-mix(in srgb,var(--border) 76%,transparent);
  --mf262-line-soft:color-mix(in srgb,var(--border-soft) 72%,transparent);
  --mf262-accent-soft:color-mix(in srgb,var(--flow) 12%,transparent);
  --mf262-accent-line:color-mix(in srgb,var(--flow) 44%,var(--border-soft));
  --mf262-shadow-soft:0 8px 28px rgba(0,0,0,.11);
  --mf262-ease:cubic-bezier(.2,.8,.2,1);
}

/* kill v261's Library-only presentation if stale DOM survived a hot render */
html[data-mf262-library="1"] #view-root .v261-library-sticky,
html[data-mf262-library="1"] #view-root .v261-library-tools{display:none!important;}

html[data-mf262-library="1"] [data-mf262-view="library"]{--mf262-library-sticky-top:12px;}
html[data-mf262-library="1"] [data-mf262-view="library"] .view-head{margin-bottom:18px;}

