.mf269-latest-track{
  scrollbar-width:none!important;-ms-overflow-style:none!important;
  cursor:grab;user-select:none;-webkit-user-select:none;
  touch-action:pan-y pinch-zoom;overscroll-behavior-inline:contain;
  scroll-behavior:auto;
}
.mf269-latest-track::-webkit-scrollbar{display:none!important;width:0!important;height:0!important;}
.mf269-latest-track.is-dragging{cursor:grabbing!important;scroll-snap-type:none!important;}
.mf269-latest-track.is-dragging *{pointer-events:none!important;}
.mf269-latest-track img{-webkit-user-drag:none;user-drag:none;pointer-events:none;}

