  body.v260-redesign :is(.view-head,.lib-toolbar,.v138-order-toolbar,.v221-settings-toolbar,.v260-recent-toolbar,.v253-history-toolbar,.batch-log-actions,.mf-batchbar){flex-wrap:wrap!important;max-width:100%!important;}
