  }
  body.v260-redesign .mobile-tabbar .mtab{
    min-height:54px!important;
    max-height:64px!important;
  }
  body.v260-redesign .main{padding-bottom:calc(86px + env(safe-area-inset-bottom))!important;}
}

@media(max-width:310px){
  body.v260-redesign .mobile-tabbar .mtab span{display:none!important;}
  body.v260-redesign .mobile-tabbar .mtab{min-height:44px!important;max-height:52px!important;}
