/* --- assets/css/143-v278-responsive-bottom-nav-visual-parity.css --- */
/* ============================================================
   MediaFlow v278 — responsive bottom navigation visual parity
   Extends the clean small-screen bottom-nav appearance through the
   complete <=1080px responsive range. v277 fixed the breakpoint; v278
   fixes the visual fallback between 861px and 1080px.
   ============================================================ */

@media(max-width:1080px){
