/* --- assets/css/222-v410-mobile-dock-sheet.css --- */
/* MediaFlow v410 — restrained mobile quick-access dock and clear action sheet.
   Extends v409 without altering desktop fan, icons, handlers, user task data,
   theme support, or the persistent Show Floating Controls preferences. */
@media screen and (max-width:720px){
  /* A single low-profile row. In v409 the progress card sat ABOVE the Add
     button, obscuring two separate sections of Dashboard content. */
  .mf397-dock{
    right:max(12px,env(safe-area-inset-right,0px));
    bottom:calc(76px + env(safe-area-inset-bottom,0px));
    flex-direction:row-reverse;
    align-items:center;
    justify-content:flex-start;
    gap:9px;
    width:auto;
    max-width:calc(100vw - 24px);
  }
  .mf397-dock .mf397-plus-holder{flex:0 0 auto;align-self:center}
  .mf397-dock .mf397-fab{
    width:48px;height:48px;border-radius:16px;
    box-shadow:0 9px 20px #0007,0 0 0 2px color-mix(in srgb,var(--flow) 17%,transparent);
  }
  .mf397-dock .mf397-fab>svg{width:24px;height:24px}
  .mf397-dock .mf397-fab::after{inset:-3px;border-radius:19px}

  /* A compact, readable 0%-100% task indicator replaces the large overlay.
     Users may expand the real task panel via the existing +/- toggle. */
  .mf397-dock .mf397-progress.compact{
    position:relative;
    flex:0 0 auto;
    width:122px;max-width:calc(100vw - 90px);
    height:48px;
    padding:7px 10px;
    border-radius:15px;
