  .mf397-dock .mf397-progress.compact .mf397-mini-percent{font-size:15px;line-height:1;font-variant-numeric:tabular-nums;margin-left:auto}
  .mf397-dock .mf397-progress.compact .mf397-collapse{width:20px;height:27px}
  .mf397-dock .mf397-progress.compact .mf397-ambient{opacity:.28}

