  transform:rotate(45deg);transition:transform .18s ease;margin-left:auto;
}
.mf437-editor>details[open]>summary{border-bottom:1px solid var(--border-soft)}
.mf437-editor>details[open]>summary::after{transform:rotate(225deg)}
