/* --- assets/css/295-v558-theme-polish.css --- */
/* MediaFlow v558: theme polish. Everything uses the active theme's own colours
   (--flow, --panel, --panel-raised, --border, --text) instead of fixed dark
   fallbacks, so it fits light, dark and every named theme. */

/* ===== Background Processes: minimised button = the + button's sibling ===== */
.mf555-proc-mini{gap:10px}
.mf555-proc-mini .mf555-proc-icon{position:relative;width:52px;height:52px;border-radius:17px;
  border:1px solid color-mix(in srgb,var(--flow) 65%,var(--border-soft,var(--border)));
  background:linear-gradient(135deg,color-mix(in srgb,var(--flow) 76%,white),var(--flow) 60%,color-mix(in srgb,var(--flow) 66%,black));
  color:var(--bg,#161616);
  box-shadow:0 12px 26px color-mix(in srgb,var(--flow) 30%,#0003),0 0 0 4px color-mix(in srgb,var(--flow) 11%,transparent);
  transition:transform .22s ease,box-shadow .22s ease}
.mf555-proc-mini .mf555-proc-icon svg{width:22px;height:22px;stroke-width:2.1}
.mf555-proc-mini:hover .mf555-proc-icon{transform:translateY(-3px);
  box-shadow:0 16px 32px color-mix(in srgb,var(--flow) 36%,#0003),0 0 0 7px color-mix(in srgb,var(--flow) 14%,transparent)}
.mf555-proc-mini:focus-visible{outline:none}
.mf555-proc-mini:focus-visible .mf555-proc-icon{outline:2px solid var(--flow);outline-offset:4px}
.mf555-proc-mini.is-active .mf555-proc-icon{animation:mf558procpulse 2.4s ease-in-out infinite}
@keyframes mf558procpulse{50%{box-shadow:0 12px 26px color-mix(in srgb,var(--flow) 30%,#0003),0 0 0 9px color-mix(in srgb,var(--flow) 16%,transparent)}}
.mf555-proc-mini.is-done .mf555-proc-icon{color:#fff;border-color:var(--healthy,#3fc7a6);
  background:linear-gradient(135deg,color-mix(in srgb,var(--healthy,#3fc7a6) 76%,white),var(--healthy,#3fc7a6))}
/* Progress: a slim pill, only while there are jobs. */
.mf555-proc-mini .mf555-proc-bar{width:58px;height:6px;background:color-mix(in srgb,var(--flow) 16%,var(--panel-raised,transparent));
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--flow) 18%,transparent)}
.mf555-proc-mini .mf555-proc-bar>i{background:linear-gradient(90deg,color-mix(in srgb,var(--flow) 70%,white),var(--flow))}
.mf555-proc-mini[data-mf558-jobs="0"] .mf555-proc-bar{display:none}
.mf558-proc-badge{position:absolute;top:-6px;right:-6px;min-width:20px;height:20px;padding:0 5px;border-radius:999px;
  display:grid;place-items:center;font:800 11px/1 var(--font-body,inherit);color:var(--flow);
  background:var(--panel,#fff);border:1.5px solid var(--flow);box-shadow:0 3px 8px #0002}
@media (prefers-reduced-motion:reduce){.mf555-proc-mini .mf555-proc-icon{animation:none!important;transition:none!important}}

/* ===== Background Processes panel: minimise matches the chevron ===== */
#mf441-process-widget .mf555-proc-minimize{width:28px;height:28px;border-radius:10px;
  border:1px solid var(--border-soft,var(--border));
  background:color-mix(in srgb,var(--panel) 87%,transparent);color:var(--flow);
  box-shadow:none;transition:border-color .2s ease,background .2s ease,color .2s ease}
#mf441-process-widget .mf555-proc-minimize svg{width:15px;height:15px;stroke-width:2.4}
#mf441-process-widget .mf555-proc-minimize:hover{border-color:color-mix(in srgb,var(--flow) 45%,var(--border-soft,var(--border)));
  background:color-mix(in srgb,var(--flow) 10%,var(--panel))}
#mf441-process-widget .mf555-proc-minimize:focus-visible{outline:2px solid var(--flow);outline-offset:2px}
#mf441-process-widget .mf555-proc-minimize:not(.mf558-placed){visibility:hidden}

/* ===== Discover verified External IDs ===== */
.mf558-id-finder{display:grid;gap:12px}
.mf558-id-finder>strong{font-size:15px;color:var(--text)}
.mf558-id-finder>p{margin:-6px 0 0;color:var(--text-dim);font-size:12.5px;line-height:1.5}
.mf558-id-finder .mf434-lookup-tools{display:flex!important;flex-wrap:wrap;gap:8px;align-items:stretch}
.mf558-id-finder .mf434-lookup-tools>input{flex:1 1 260px!important;min-width:0;width:auto!important}
.mf558-id-finder .mf434-lookup-tools>select{flex:0 1 210px!important;min-width:150px;width:auto!important}
.mf558-id-finder .mf434-lookup-tools>.btn{flex:0 0 auto}
.mf558-id-finder .mf434-lookup-tools>input,.mf558-id-finder .mf434-lookup-tools>select{height:42px;min-height:42px;border-radius:12px;
  border:1px solid var(--border-soft,var(--border));background-color:var(--panel-raised);color:var(--text)}
.mf558-id-finder .mf434-lookup-tools>input:focus,.mf558-id-finder .mf434-lookup-tools>select:focus{outline:none;border-color:var(--flow);
  box-shadow:0 0 0 3px color-mix(in srgb,var(--flow) 18%,transparent)}
.btn.mf558-find-ids{height:42px;min-height:42px;padding:0 18px;border-radius:12px;display:inline-flex;align-items:center;justify-content:center;gap:8px;font-weight:750}

/* Primary buttons in these surfaces: the MediaFlow accent. */
.mf558-id-finder .btn-primary,#mf555-log-popup .btn-primary,#mf555-log-popup .mf378-library-actions .btn-primary{
  background:linear-gradient(135deg,color-mix(in srgb,var(--flow) 82%,white),var(--flow))!important;
  border:1px solid color-mix(in srgb,var(--flow) 80%,black)!important;color:#fff!important;
  box-shadow:0 6px 16px color-mix(in srgb,var(--flow) 28%,transparent)!important}
.mf558-id-finder .btn-primary:hover:not(:disabled),#mf555-log-popup .btn-primary:hover:not(:disabled){filter:brightness(1.05);transform:translateY(-1px)}
.mf558-id-finder .btn-primary:disabled,#mf555-log-popup .btn-primary:disabled{opacity:.45;box-shadow:none!important;transform:none;cursor:not-allowed}
.mf558-id-finder .btn-primary svg,#mf555-log-popup .btn-primary svg{color:#fff;stroke:#fff}

/* Site status chips, grouped */
.mf558-sr{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.mf558-id-status{display:grid;gap:8px;margin:2px 0 0}
.mf558-chip-group{display:flex;flex-wrap:wrap;align-items:center;gap:6px}
.mf558-chip-label{font-size:10.5px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--text-mute,var(--text-dim));min-width:96px}
.mf558-chip{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 11px;border-radius:999px;font-size:12px;line-height:1;
  border:1px solid var(--border-soft,var(--border));background:var(--panel);color:var(--text-dim);white-space:nowrap;cursor:default}
.mf558-chip b{display:inline-grid;place-items:center;min-width:20px;height:18px;padding:0 6px;border-radius:999px;font-size:11px;
  background:var(--flow);color:#fff}
.mf558-chip em{font-style:normal;font-weight:700}
.mf558-chip.is-found{border-color:color-mix(in srgb,var(--flow) 40%,var(--border-soft,var(--border)));background:color-mix(in srgb,var(--flow) 9%,var(--panel));color:var(--text)}
.mf558-chip.is-none{opacity:.75}
.mf558-chip.is-error{border-color:color-mix(in srgb,var(--overused,#e8607a) 38%,var(--border-soft,var(--border)));
  background:color-mix(in srgb,var(--overused,#e8607a) 7%,var(--panel));color:var(--text)}
.mf558-chip.is-error em{color:color-mix(in srgb,var(--overused,#e8607a) 85%,var(--text))}
.mf558-spin{width:11px;height:11px;border-radius:50%;border:2px solid color-mix(in srgb,var(--flow) 25%,transparent);border-top-color:var(--flow);animation:mf558spin .8s linear infinite}
@keyframes mf558spin{to{transform:rotate(360deg)}}
@media (max-width:640px){.mf558-chip-label{min-width:0;width:100%}}

/* Result groups */
.mf558-id-group{margin:0;padding:6px;border:1px solid var(--border-soft,var(--border));border-radius:16px;background:var(--panel);display:grid;gap:2px;min-width:0}
.mf558-id-group>legend{display:flex;align-items:baseline;gap:8px;padding:0 8px;font-size:13px;font-weight:800;color:var(--text)}
.mf558-id-group>legend small{font-weight:600;color:var(--text-dim);font-size:11.5px}
.mf558-id-row{display:grid!important;grid-template-columns:22px minmax(0,1fr) auto auto;align-items:center;gap:12px;
  padding:10px 12px;margin:0;border-radius:12px;border:1px solid transparent;cursor:pointer;transition:background .15s ease,border-color .15s ease}
.mf558-id-row:hover{background:color-mix(in srgb,var(--flow) 6%,transparent)}
.mf558-id-row:has(input:checked){background:color-mix(in srgb,var(--flow) 10%,var(--panel));border-color:color-mix(in srgb,var(--flow) 35%,transparent)}
.mf558-id-row.is-none{grid-template-columns:22px minmax(0,1fr)}
.mf558-id-row.is-none .mf555-id-main b{font-weight:600;color:var(--text-dim)}
.mf558-id-row .mf555-id-main{display:grid;gap:3px;min-width:0}
.mf558-id-row .mf555-id-main b{font-size:13.5px;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mf558-id-row .mf555-id-main small{font-size:11.5px;color:var(--text-dim);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* Round radio: fixed size, never stretched into an oval. */
.mf558-id-finder .mf558-id-row input.mf558-radio[type=radio]{appearance:none!important;-webkit-appearance:none!important;accent-color:var(--flow);flex:0 0 20px;width:20px!important;height:20px!important;min-width:20px;min-height:20px;
  max-width:20px;max-height:20px;margin:0!important;padding:0!important;border-radius:50%!important;box-sizing:border-box;
  border:2px solid color-mix(in srgb,var(--flow) 45%,var(--border))!important;background:var(--panel)!important;outline:none!important;cursor:pointer;
  display:grid!important;place-items:center;transition:border-color .15s ease,box-shadow .15s ease}
.mf558-id-finder .mf558-id-row input.mf558-radio[type=radio]::before{content:'';width:10px;height:10px;border-radius:50%;background:var(--flow);transform:scale(0);transition:transform .15s ease}
.mf558-id-finder .mf558-id-row input.mf558-radio[type=radio]:checked{border-color:var(--flow)!important}
.mf558-id-finder .mf558-id-row input.mf558-radio[type=radio]:checked::before{transform:scale(1)}
.mf558-id-finder .mf558-id-row input.mf558-radio[type=radio]:focus-visible{box-shadow:0 0 0 4px color-mix(in srgb,var(--flow) 22%,transparent)!important}

.mf558-tag{display:inline-flex;align-items:center;gap:4px;height:22px;padding:0 9px;border-radius:999px;font-size:11px;font-weight:700;white-space:nowrap;
  color:color-mix(in srgb,var(--flow) 85%,var(--text));background:color-mix(in srgb,var(--flow) 12%,transparent)}
.mf558-tag.is-exact{color:color-mix(in srgb,var(--healthy,#3fc7a6) 75%,var(--text));background:color-mix(in srgb,var(--healthy,#3fc7a6) 14%,transparent)}
.mf558-tag svg{width:12px;height:12px}
.mf558-id-open{display:grid;place-items:center;width:32px;height:32px;border-radius:10px;border:1px solid var(--border-soft,var(--border));
  background:var(--panel);color:var(--text-dim);text-decoration:none!important}
.mf558-id-open:hover{color:var(--flow);border-color:color-mix(in srgb,var(--flow) 45%,var(--border))}
.mf558-id-open svg{width:15px;height:15px}
@media (max-width:640px){
  .mf558-id-row{grid-template-columns:22px minmax(0,1fr) auto;row-gap:6px}
  .mf558-id-row .mf558-tag{grid-column:2;justify-self:start;grid-row:2}
  .mf558-id-row .mf558-id-open{grid-column:3;grid-row:1}
}

/* Already linked: one compact list */
.mf558-linked{border:1px solid var(--border-soft,var(--border));border-radius:16px;background:var(--panel);overflow:hidden}
.mf558-linked>header{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--border-soft,var(--border));
  background:color-mix(in srgb,var(--flow) 5%,var(--panel))}
.mf558-linked>header svg{width:15px;height:15px;color:var(--flow)}
.mf558-linked>header span{font-size:13px;font-weight:800;color:var(--text)}
.mf558-linked>header small{margin-left:auto;font-size:11px;color:var(--text-dim)}
.mf558-linked ul{list-style:none;margin:0;padding:4px 6px}
.mf558-linked-row{display:grid;grid-template-columns:minmax(96px,130px) auto minmax(0,1fr) auto;align-items:center;gap:12px;padding:8px;border-radius:10px}
.mf558-linked-row+.mf558-linked-row{border-top:1px solid color-mix(in srgb,var(--border-soft,var(--border)) 70%,transparent)}
.mf558-linked-site{font-size:12.5px;font-weight:750;color:var(--text)}
.mf558-linked-row code{font:600 11.5px/1 ui-monospace,SFMono-Regular,Menlo,monospace;padding:5px 8px;border-radius:8px;
  background:color-mix(in srgb,var(--flow) 9%,var(--panel-raised));color:var(--text)}
.mf558-linked-title{font-size:12px;color:var(--text-dim);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mf558-kept{font-size:10.5px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;color:var(--text-mute,var(--text-dim))}
@media (max-width:640px){.mf558-linked-row{grid-template-columns:auto auto 1fr}.mf558-linked-title{grid-column:1/-1;grid-row:2}}

.mf558-id-actions{display:flex;justify-content:flex-end}
.btn.mf558-id-add{height:42px;padding:0 18px;border-radius:12px;display:inline-flex;align-items:center;gap:8px;font-weight:750}
.btn.mf558-id-add svg{width:16px;height:16px}
.mf558-id-empty{margin:0;padding:14px;border-radius:14px;border:1px dashed var(--border-soft,var(--border));color:var(--text-dim);font-size:12.5px}

/* ===== Add to Logging popup: follows the theme ===== */
#mf555-log-popup .mf555-log-backdrop,#mf558-log-skeleton .mf555-log-backdrop{background:color-mix(in srgb,var(--bg,#000) 38%,rgba(10,10,20,.42));backdrop-filter:blur(6px)}
#mf555-log-popup .mf555-log-sheet,#mf558-log-skeleton .mf555-log-sheet{background:var(--panel);color:var(--text);
  border:1px solid var(--border-soft,var(--border));border-radius:24px;
  box-shadow:0 30px 80px color-mix(in srgb,var(--flow) 12%,rgba(0,0,0,.28)),0 2px 0 color-mix(in srgb,var(--text) 4%,transparent) inset}
#mf555-log-popup .mf555-log-head,#mf558-log-skeleton .mf555-log-head{padding:16px 18px 14px 20px;border-bottom:1px solid var(--border-soft,var(--border));
