/* Every control in the popup: one consistent look */
#mf555-log-popup .v238-log-library-body .field-label{color:var(--text-dim)!important;font-size:11px!important;font-weight:800!important;letter-spacing:.05em;text-transform:uppercase}
#mf555-log-popup .v238-log-library-body :is(input:not([type=checkbox]):not([type=radio]),select,summary.btn,.btn){
  min-height:40px;border-radius:12px!important;border:1px solid var(--border-soft,var(--border))!important;
  background-color:var(--panel-raised)!important;color:var(--text)!important;box-shadow:none!important;font-weight:650}
#mf555-log-popup .v238-log-library-body :is(input:not([type=checkbox]):not([type=radio]),select):focus{outline:none!important;border-color:var(--flow)!important;
  box-shadow:0 0 0 3px color-mix(in srgb,var(--flow) 18%,transparent)!important}
